window.SSStorage={get(k){try{return localStorage.getItem(k)}catch{return null}},set(k,v){try{localStorage.setItem(k,v);return true}catch{return false}},remove(k){try{localStorage.removeItem(k);return true}catch{return false}},read(k,f=null){try{return JSON.parse(this.get(k)||'null')??f}catch{return f}}};function ssViewport(){const v=window.visualViewport;document.documentElement.style.setProperty('--vh',(v?v.height:innerHeight)+'px');document.documentElement.style.setProperty('--vtop',(v?v.offsetTop:0)+'px')}ssViewport();addEventListener('resize',ssViewport);if(window.visualViewport){visualViewport.addEventListener('resize',ssViewport);visualViewport.addEventListener('scroll',ssViewport)}